# Focus logger: macOS installer

This is a working, tested installer. Write it to a temp file on the user's Mac (Shell with that machineId), run it with `bash`, then run `~/.focuslog/focus-report` after 1-2 minutes to verify. It needs `swiftc` (Xcode Command Line Tools: `xcode-select --install`). Adjust the site maps (hostMap/titleMap) to the owner's distraction list if wanted.

```bash
#!/bin/bash
# focuslog installer for macOS: local, per-user foreground-app time logger (no network).
# Writes ~/.focuslog/{focuslog,focus-report,src/main.swift} and ~/Library/LaunchAgents/com.user.focuslog.plist,
# compiles with swiftc (Xcode or Command Line Tools), and starts it via launchctl.
# Reader:   ~/.focuslog/focus-report    (previous complete hour + current partial hour)
# Uninstall:
#   launchctl bootout gui/$(id -u)/com.user.focuslog
#   rm -f ~/Library/LaunchAgents/com.user.focuslog.plist
#   rm -rf ~/.focuslog
# Permissions: the first time Chrome/Brave/Safari/Arc/Edge is frontmost, macOS may ask to let "focuslog"
# control that browser (Automation) so the active tab title/URL can be read. Optional: granting
# Accessibility (or Screen Recording) to ~/.focuslog/focuslog adds window titles for other apps.
set -euo pipefail
command -v swiftc >/dev/null || { echo "swiftc not found: run xcode-select --install" >&2; exit 1; }
FL="$HOME/.focuslog"; LABEL=com.user.focuslog; PLIST="$HOME/Library/LaunchAgents/$LABEL.plist"
mkdir -p "$FL/summary" "$FL/src" "$HOME/Library/LaunchAgents"
cat > "$FL/src/main.swift" <<'SWIFT_EOF'
// focuslog: tiny local foreground-app time logger. No network. Hourly aggregates in ~/.focuslog/summary
import Cocoa
import ApplicationServices

let fm = FileManager.default
let base = NSHomeDirectory() + "/.focuslog"
let sumDir = base + "/summary"
let interval: TimeInterval = 5
let idleThreshold: Double = 300   // 5+ min without input => idle
let pendingAfter: Double = 60     // samples after 60s w/o input are held until we know if it became idle
let maxEntries = 15
let retentionDays: Double = 14
let posix = Locale(identifier: "en_US_POSIX")
func mkFmt(_ f: String) -> DateFormatter { let d = DateFormatter(); d.locale = posix; d.dateFormat = f; return d }
let keyFmt = mkFmt("yyyy-MM-dd_HH")
let isoFmt = mkFmt("yyyy-MM-dd'T'HH:mm:ssxxxxx")
let hmFmt = mkFmt("HH:mm")
let dayFmt = mkFmt("EEE MMM d")
let machine = Host.current().localizedName ?? "Mac"

func hourStart(_ d: Date) -> Date { Calendar.current.dateInterval(of: .hour, for: d)!.start }
func pathFor(_ s: Date) -> String { sumDir + "/" + keyFmt.string(from: s) + ".json" }
func num(_ a: Any?) -> Double { (a as? NSNumber)?.doubleValue ?? 0 }
func readJSON(_ p: String) -> [String: Any]? { guard let d = fm.contents(atPath: p) else { return nil }; return (try? JSONSerialization.jsonObject(with: d)) as? [String: Any] }
func short(_ s: String, _ n: Int = 80) -> String {
  let t = s.replacingOccurrences(of: "\n", with: " ").trimmingCharacters(in: .whitespaces)
  return t.count > n ? String(t.prefix(n - 1)) + "…" : t
}

final class HourAgg {
  let start: Date
  var active = 0.0, idle = 0.0
  var apps: [String: Double] = [:], acts: [String: Double] = [:]
  init(_ s: Date) {
    start = s
    if let j = readJSON(pathFor(s)) {  // resume after restart
      active = num(j["active_seconds"]); idle = num(j["idle_seconds"])
      apps = HourAgg.entries(j["by_app"]); acts = HourAgg.entries(j["by_activity"])
    }
  }
  static func entries(_ a: Any?) -> [String: Double] {
    var r: [String: Double] = [:]
    for e in (a as? [[String: Any]]) ?? [] { if let n = e["name"] as? String { r[n, default: 0] += num(e["seconds"]) } }
    return r
  }
  static func top(_ m: [String: Double]) -> [[String: Any]] {
    let items = m.filter { $0.key != "(other)" }.sorted { $0.value > $1.value }
    var out: [[String: Any]] = items.prefix(maxEntries).map { ["name": $0.key, "seconds": Int($0.value.rounded())] }
    let other = items.dropFirst(maxEntries).reduce(0.0) { $0 + $1.value } + (m["(other)"] ?? 0)
    if other >= 1 { out.append(["name": "(other)", "seconds": Int(other.rounded())]) }
    return out
  }
  func save() {
    let j: [String: Any] = ["hour_start": isoFmt.string(from: start), "machine": machine,
      "active_seconds": Int(active.rounded()), "idle_seconds": Int(idle.rounded()),
      "updated_at": isoFmt.string(from: Date()), "by_app": HourAgg.top(apps), "by_activity": HourAgg.top(acts)]
    guard let d = try? JSONSerialization.data(withJSONObject: j, options: [.prettyPrinted, .sortedKeys]) else { return }
    try? d.write(to: URL(fileURLWithPath: pathFor(start)), options: .atomic)
  }
}

func cleanup() {
  let cutoff = Date().addingTimeInterval(-retentionDays * 86400)
  for f in (try? fm.contentsOfDirectory(atPath: sumDir)) ?? [] where f.hasSuffix(".json") {
    let p = sumDir + "/" + f
    if let m = (try? fm.attributesOfItem(atPath: p))?[.modificationDate] as? Date, m < cutoff { try? fm.removeItem(atPath: p) }
  }
}

// ---- site / title classification ----
let hostMap: [(String, String)] = [("x.com","X (Twitter)"),("twitter.com","X (Twitter)"),("youtube.com","YouTube"),("youtu.be","YouTube"),
  ("reddit.com","Reddit"),("facebook.com","Facebook"),("instagram.com","Instagram"),("tiktok.com","TikTok"),("linkedin.com","LinkedIn"),
  ("mail.google.com","Gmail"),("calendar.google.com","Google Calendar"),("docs.google.com","Google Docs"),("drive.google.com","Google Drive"),
  ("slack.com","Slack"),("github.com","GitHub"),("ticktick.com","TickTick"),("news.ycombinator.com","Hacker News"),("netflix.com","Netflix"),
  ("twitch.tv","Twitch"),("amazon.com","Amazon"),("chatgpt.com","ChatGPT"),("claude.ai","Claude"),("grok.com","Grok"),("notion.so","Notion"),
  ("stackoverflow.com","Stack Overflow"),("salesforce.com","Salesforce"),("force.com","Salesforce"),("roblox.com","Roblox")]
let titleMap: [(String, String)] = [("youtube","YouTube"),("reddit","Reddit"),("facebook","Facebook"),("instagram","Instagram"),("tiktok","TikTok"),
  ("linkedin","LinkedIn"),("gmail","Gmail"),("slack","Slack"),("github","GitHub"),("ticktick","TickTick"),("netflix","Netflix"),("twitch","Twitch"),
  ("chatgpt","ChatGPT"),("hacker news","Hacker News"),("google calendar","Google Calendar"),("google docs","Google Docs"),("notion","Notion"),
  ("stack overflow","Stack Overflow"),("salesforce","Salesforce")]
func siteLabel(title: String, url: String) -> String {
  var host = URL(string: url)?.host?.lowercased() ?? ""
  if host.hasPrefix("www.") { host.removeFirst(4) }
  for (d, l) in hostMap where host == d || host.hasSuffix("." + d) { return l }
  let t = title.lowercased()
  if t.hasSuffix(" / x") || t.contains(" on x: ") || t.contains("x.com") || t.contains("twitter") { return "X (Twitter)" }
  for (k, l) in titleMap where t.contains(k) { return l }
  if !host.isEmpty { return "Web: " + host }
  return title.isEmpty ? "Web: (untitled)" : "Web: " + short(title, 70)
}

let chromeLike: Set<String> = ["com.google.Chrome","com.google.Chrome.beta","com.brave.Browser","com.microsoft.edgemac","company.thebrowser.Browser","com.vivaldi.Vivaldi"]
let otherBrowsers: Set<String> = ["org.mozilla.firefox","com.operasoftware.Opera","com.apple.Safari"]

func axTitle(_ pid: pid_t) -> String? {
  guard AXIsProcessTrusted() else { return nil }   // only if user granted Accessibility; never prompts
  let app = AXUIElementCreateApplication(pid)
  var w: CFTypeRef?
  guard AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute as CFString, &w) == .success, let win = w else { return nil }
  var t: CFTypeRef?
  guard AXUIElementCopyAttributeValue(win as! AXUIElement, kAXTitleAttribute as CFString, &t) == .success else { return nil }
  return t as? String
}
func cgTitle(_ pid: pid_t) -> String? {   // window names are only visible with Screen Recording permission; otherwise nil
  guard let list = CGWindowListCopyWindowInfo([.optionOnScreenOnly, .excludeDesktopElements], kCGNullWindowID) as? [[String: Any]] else { return nil }
  for w in list where (w[kCGWindowOwnerPID as String] as? Int32) == pid && (w[kCGWindowLayer as String] as? Int) == 0 {
    if let n = w[kCGWindowName as String] as? String, !n.isEmpty { return n }
  }
  return nil
}
func windowTitle(_ pid: pid_t) -> String? { axTitle(pid) ?? cgTitle(pid) }

func screenOff() -> Bool {
  if CGDisplayIsAsleep(CGMainDisplayID()) != 0 { return true }
  guard let d = CGSessionCopyCurrentDictionary() as? [String: Any] else { return true }
  if (d["CGSSessionScreenIsLocked"] as? Bool) == true { return true }
  if (d["kCGSSessionOnConsoleKey"] as? Bool) == false { return true }
  return false
}

final class Logger {
  var cur = HourAgg(hourStart(Date()))
  var last = Date()
  var lastFlush = Date()
  var pending: [(String, String, Double)] = []
  var scripts: [String: NSAppleScript] = [:]
  var asBackoff: [String: Date] = [:]

  func browserTab(_ bid: String) -> (String, String)? {
    if let u = asBackoff[bid], u > Date() { return nil }
    let tabExpr: String
    if bid == "com.apple.Safari" { tabExpr = "set t to current tab of front window\nreturn (name of t) & linefeed & (URL of t)" }
    else if chromeLike.contains(bid) { tabExpr = "set t to active tab of front window\nreturn (title of t) & linefeed & (URL of t)" }
    else { return nil }
    let s = scripts[bid] ?? NSAppleScript(source: "tell application id \"\(bid)\"\nif (count of windows) is 0 then return \"\"\n\(tabExpr)\nend tell")!
    scripts[bid] = s
    var err: NSDictionary?
    let r = s.executeAndReturnError(&err)
    if let e = err {
      let code = (e[NSAppleScript.errorNumber] as? Int) ?? 0
      if code == -1743 || code == -1744 { asBackoff[bid] = Date().addingTimeInterval(600) }  // Automation denied
      return nil
    }
    let parts = (r.stringValue ?? "").components(separatedBy: "\n")
    return (parts.first ?? "", parts.count > 1 ? parts[1] : "")
  }

  func classify(_ app: NSRunningApplication) -> (String, String) {
    let name = app.localizedName ?? app.bundleIdentifier ?? "Unknown"
    let bid = app.bundleIdentifier ?? ""
    if chromeLike.contains(bid) || otherBrowsers.contains(bid) {
      var title = "", url = ""
      if let tab = browserTab(bid) { title = tab.0; url = tab.1 } else { title = windowTitle(app.processIdentifier) ?? "" }
      for suf in [" — Mozilla Firefox", " - Mozilla Firefox", " - Google Chrome", " - Brave", " - Opera"] where title.hasSuffix(suf) { title = String(title.dropLast(suf.count)) }
      if title.isEmpty && url.isEmpty { return (name, name + " (no tab info)") }
      return (name, siteLabel(title: title, url: url))
    }
    if let t = windowTitle(app.processIdentifier), !t.isEmpty, t != name { return (name, name + ": " + short(t)) }
    return (name, name)
  }

  func commitPending(active: Bool) {
    for (a, l, d) in pending {
      if active { cur.active += d; cur.apps[a, default: 0] += d; cur.acts[l, default: 0] += d } else { cur.idle += d }
    }
    pending.removeAll()
  }

  func tick() {
    let now = Date()
    var dt = now.timeIntervalSince(last); last = now
    if dt <= 0 || dt > interval * 3 { dt = interval }   // after sleep, don't count the gap
    let hs = hourStart(now)
    if hs != cur.start { cur.save(); cur = HourAgg(hs); cleanup() }
    let idleS = CGEventSource.secondsSinceLastEventType(.combinedSessionState, eventType: CGEventType(rawValue: ~0)!)
    let front = NSWorkspace.shared.frontmostApplication
    let fname = front?.localizedName ?? ""
    if front == nil || screenOff() || fname == "loginwindow" || fname == "ScreenSaverEngine" || idleS >= idleThreshold {
      commitPending(active: false); cur.idle += dt
    } else {
      let (a, l) = classify(front!)
      if idleS < pendingAfter { commitPending(active: true); cur.active += dt; cur.apps[a, default: 0] += dt; cur.acts[l, default: 0] += dt }
      else { pending.append((a, l, dt)) }
    }
    if now.timeIntervalSince(lastFlush) >= 60 { cur.save(); lastFlush = now }
  }
}

func fmtDur(_ s: Double) -> String {
  let t = Int(s.rounded()); let h = t / 3600, m = (t % 3600) / 60, sec = t % 60
  if h > 0 { return "\(h)h\(String(format: "%02d", m))m" }
  if m > 0 { return "\(m)m\(String(format: "%02d", sec))s" }
  return "\(sec)s"
}
func report() {
  let cs = hourStart(Date())
  for (st, tag) in [(cs.addingTimeInterval(-3600), "previous hour"), (cs, "current hour, partial")] {
    let span = "\(dayFmt.string(from: st)) \(hmFmt.string(from: st))-\(hmFmt.string(from: st.addingTimeInterval(3600)))"
    guard let j = readJSON(pathFor(st)) else { print("== \(span) (\(tag)): no data"); continue }
    let upd = (j["updated_at"] as? String).flatMap { isoFmt.date(from: $0) }.map { hmFmt.string(from: $0) } ?? "?"
    print("== \(span) (\(tag)) [\(j["machine"] as? String ?? machine)] active \(fmtDur(num(j["active_seconds"]))), idle \(fmtDur(num(j["idle_seconds"]))), updated \(upd)")
    let apps = ((j["by_app"] as? [[String: Any]]) ?? []).prefix(6).map { "\($0["name"] as? String ?? "?") \(fmtDur(num($0["seconds"])))" }
    if !apps.isEmpty { print("   apps: " + apps.joined(separator: ", ")) }
    for e in ((j["by_activity"] as? [[String: Any]]) ?? []).prefix(10) {
      print("   " + fmtDur(num(e["seconds"])).padding(toLength: 8, withPad: " ", startingAt: 0) + (e["name"] as? String ?? "?"))
    }
  }
}

try? fm.createDirectory(atPath: sumDir, withIntermediateDirectories: true)
let args = CommandLine.arguments
if args.count > 1 && args[1] == "report" { report(); exit(0) }
cleanup()
let logger = Logger()
signal(SIGTERM, SIG_IGN); signal(SIGINT, SIG_IGN)
var sigs: [DispatchSourceSignal] = []
for sg in [SIGTERM, SIGINT] {
  let s = DispatchSource.makeSignalSource(signal: sg, queue: .main)
  s.setEventHandler { logger.commitPending(active: true); logger.cur.save(); exit(0) }
  s.resume(); sigs.append(s)
}
let timer = Timer(timeInterval: interval, repeats: true) { _ in logger.tick() }
timer.tolerance = 1
RunLoop.main.add(timer, forMode: .default)
logger.tick()
RunLoop.main.run()
SWIFT_EOF
cat > "$FL/focus-report" <<'REPORT_EOF'
#!/bin/sh
# Prints previous complete hour + current partial hour of foreground-app time.
exec "$HOME/.focuslog/focuslog" report
REPORT_EOF
chmod +x "$FL/focus-report"
( cd "$FL" && swiftc -O -swift-version 5 -o focuslog src/main.swift )
cat > "$PLIST" <<PLIST_EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>com.user.focuslog</string>
  <key>ProgramArguments</key><array><string>$HOME/.focuslog/focuslog</string></array>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>ThrottleInterval</key><integer>30</integer>
  <key>LowPriorityIO</key><true/>
  <key>Nice</key><integer>10</integer>
  <key>StandardErrorPath</key><string>$HOME/.focuslog/focuslog.err.log</string>
  <key>StandardOutPath</key><string>/dev/null</string>
</dict></plist>
PLIST_EOF
plutil -lint "$PLIST" >/dev/null
launchctl bootout "gui/$(id -u)/$LABEL" 2>/dev/null || true
launchctl bootstrap "gui/$(id -u)" "$PLIST"
sleep 2
launchctl print "gui/$(id -u)/$LABEL" | grep -E '^\s*(state|pid) =' || true
echo "Installed. Summaries: $FL/summary  Reader: $FL/focus-report"
```

---
name: focus-logger-windows-installer
description: >-
  Use this when installing the focus logger on a Windows computer; it holds the
  complete, tested one-shot PowerShell installer (logger, reader, hidden
  per-user Scheduled Task).
---
# Focus logger: Windows installer

This is a working, tested installer. Write it to `%TEMP%\install-focuslog.ps1` on the user's PC (Shell with that machineId), run `powershell -NoProfile -ExecutionPolicy Bypass -File` on it (no admin needed), then run `& "$env:USERPROFILE\.focuslog\focus-report.ps1"` after 1-2 minutes to verify. Adjust $TitleMap / $Nice to the owner's apps if wanted.

```powershell
# focuslog installer for Windows: local, per-user foreground-window time logger (no network, no admin).
# Writes %USERPROFILE%\.focuslog\{focuslog.ps1,focus-report.ps1,focuslog.vbs}, registers a per-user
# "FocusLog" Scheduled Task (at logon, hidden via wscript), falls back to a Startup-folder .vbs, and starts it.
# Run:      powershell -NoProfile -ExecutionPolicy Bypass -File .\install-win.ps1
# Reader:   & "$env:USERPROFILE\.focuslog\focus-report.ps1"
# Uninstall:
#   Unregister-ScheduledTask FocusLog -Confirm:$false -ErrorAction SilentlyContinue
#   Remove-Item (Join-Path ([Environment]::GetFolderPath('Startup')) 'FocusLog.vbs') -ErrorAction SilentlyContinue
#   Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" | ? CommandLine -like '*focuslog.ps1*' | % { Stop-Process -Id $_.ProcessId }
#   Remove-Item -Recurse -Force "$env:USERPROFILE\.focuslog"
$ErrorActionPreference = 'Stop'
$B = Join-Path $env:USERPROFILE '.focuslog'
New-Item -ItemType Directory -Force (Join-Path $B 'summary') | Out-Null
$enc = New-Object Text.UTF8Encoding($false)
$logger = @'
# focuslog.ps1 - tiny local foreground-window time logger (no network). Hourly aggregates in %USERPROFILE%\.focuslog\summary
$ErrorActionPreference = 'SilentlyContinue'
$mtx = New-Object System.Threading.Mutex($false, 'Local\FocusLogUser')
if (-not $mtx.WaitOne(0)) { exit }
$Base = Join-Path $env:USERPROFILE '.focuslog'
$SumDir = Join-Path $Base 'summary'
New-Item -ItemType Directory -Force -Path $SumDir | Out-Null
Add-Type -TypeDefinition @"
using System; using System.Runtime.InteropServices; using System.Text;
public static class FL {
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [StructLayout(LayoutKind.Sequential)] public struct LASTINPUTINFO { public uint cbSize; public uint dwTime; }
  [DllImport("user32.dll")] public static extern bool GetLastInputInfo(ref LASTINPUTINFO i);
  [DllImport("user32.dll", SetLastError=true)] public static extern IntPtr OpenInputDesktop(uint f, bool inh, uint acc);
  [DllImport("user32.dll")] public static extern bool CloseDesktop(IntPtr h);
  public static double IdleSeconds() { LASTINPUTINFO i = new LASTINPUTINFO(); i.cbSize = (uint)Marshal.SizeOf(i); if (!GetLastInputInfo(ref i)) return 0; return unchecked((uint)Environment.TickCount - i.dwTime) / 1000.0; }
  public static string Title(IntPtr h) { StringBuilder sb = new StringBuilder(512); GetWindowText(h, sb, 512); return sb.ToString(); }
  public static bool Locked() { IntPtr d = OpenInputDesktop(0, false, 0x0100); if (d == IntPtr.Zero) return true; CloseDesktop(d); return false; }
}
"@
$Interval = 5; $IdleThreshold = 300; $PendingAfter = 60; $MaxEntries = 15; $RetentionDays = 14
$Machine = $env:COMPUTERNAME
$Browsers = @{ chrome='Google Chrome'; brave='Brave'; firefox='Firefox'; msedge='Microsoft Edge'; opera='Opera'; vivaldi='Vivaldi'; arc='Arc' }
$Nice = @{ Code='VS Code'; RobloxStudioBeta='Roblox Studio'; explorer='File Explorer'; WindowsTerminal='Windows Terminal'; ApplicationFrameHost='Windows App' }
$TitleMap = @(@('youtube','YouTube'),@('reddit','Reddit'),@('facebook','Facebook'),@('instagram','Instagram'),@('tiktok','TikTok'),
  @('linkedin','LinkedIn'),@('gmail','Gmail'),@('slack','Slack'),@('github','GitHub'),@('ticktick','TickTick'),@('netflix','Netflix'),@('twitch','Twitch'),
  @('chatgpt','ChatGPT'),@('hacker news','Hacker News'),@('google calendar','Google Calendar'),@('google docs','Google Docs'),@('notion','Notion'),
  @('stack overflow','Stack Overflow'),@('salesforce','Salesforce'),@('roblox','Roblox'),@('amazon','Amazon'))
function Short([string]$s, [int]$n = 80) { $s = ($s -replace '\s+', ' ').Trim(); if ($s.Length -gt $n) { $s.Substring(0, $n - 3) + '...' } else { $s } }
function SiteLabel([string]$t) {
  $l = $t.ToLowerInvariant()
  if ($l.EndsWith(' / x') -or $l.Contains(' on x: ') -or $l.Contains('x.com') -or $l.Contains('twitter')) { return 'X (Twitter)' }
  foreach ($p in $TitleMap) { if ($l.Contains($p[0])) { return $p[1] } }
  return 'Web: ' + (Short $t 70)
}
function Classify([string]$proc, [string]$title) {
  if ($Browsers.ContainsKey($proc)) {
    $app = $Browsers[$proc]
    $t = $title -replace '\s+[-\u2013\u2014]\s+(Google Chrome|Brave|Mozilla Firefox|Microsoft.{0,2}\s?Edge|Opera|Vivaldi)$', ''
    if ($t -match '^\s*$' -or $t -eq $app) { return @($app, "$app (no tab info)") }
    return @($app, (SiteLabel $t))
  }
  $app = if ($Nice.ContainsKey($proc)) { $Nice[$proc] } elseif ($proc) { $proc } else { 'Unknown' }
  $t = Short $title
  if ($t -and $t -ne $app -and $t -ne $proc) { return @($app, "${app}: $t") }
  return @($app, $app)
}
function HourStart([datetime]$d) { New-Object DateTime($d.Year, $d.Month, $d.Day, $d.Hour, 0, 0, [DateTimeKind]::Local) }
function PathFor([datetime]$s) { Join-Path $SumDir ($s.ToString('yyyy-MM-dd_HH') + '.json') }
function NewHour([datetime]$s) {
  $h = @{ start = $s; active = 0.0; idle = 0.0; apps = @{}; acts = @{} }
  $p = PathFor $s
  if (Test-Path $p) { try {
    $j = Get-Content $p -Raw | ConvertFrom-Json
    $h.active = [double]$j.active_seconds; $h.idle = [double]$j.idle_seconds
    foreach ($e in @($j.by_app)) { if ($e.name) { $h.apps[[string]$e.name] = [double]$e.seconds } }
    foreach ($e in @($j.by_activity)) { if ($e.name) { $h.acts[[string]$e.name] = [double]$e.seconds } }
  } catch {} }
  return $h
}
function Top($m) {
  $out = New-Object System.Collections.ArrayList
  $other = 0.0; if ($m.ContainsKey('(other)')) { $other = [double]$m['(other)'] }
  $i = 0
  foreach ($it in ($m.GetEnumerator() | Where-Object { $_.Key -ne '(other)' } | Sort-Object Value -Descending)) {
    if ($i -lt $MaxEntries) { [void]$out.Add([ordered]@{ name = $it.Key; seconds = [int][math]::Round($it.Value) }) } else { $other += $it.Value }
    $i++
  }
  if ($other -ge 1) { [void]$out.Add([ordered]@{ name = '(other)'; seconds = [int][math]::Round($other) }) }
  return ,$out.ToArray()
}
function Save($h) {
  $o = [ordered]@{ hour_start = $h.start.ToString('yyyy-MM-ddTHH:mm:sszzz'); machine = $Machine
    active_seconds = [int][math]::Round($h.active); idle_seconds = [int][math]::Round($h.idle)
    updated_at = (Get-Date).ToString('yyyy-MM-ddTHH:mm:sszzz'); by_app = (Top $h.apps); by_activity = (Top $h.acts) }
  $json = ConvertTo-Json -InputObject $o -Depth 5
  $p = PathFor $h.start; $tmp = "$p.tmp"
  [IO.File]::WriteAllText($tmp, $json, (New-Object Text.UTF8Encoding($false)))
  Move-Item -LiteralPath $tmp -Destination $p -Force
}
function Cleanup { $cut = (Get-Date).AddDays(-$RetentionDays); Get-ChildItem $SumDir -Filter *.json | Where-Object { $_.LastWriteTime -lt $cut } | Remove-Item -Force }
